pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint96 a, uint96 b) public {
        vm.assume(actor != address(0));
        vm.assume(a > 0 && b > 0 && b < type(uint256).max - a);

        // first deposit of a, then withdraw (must pay out and clear the entry)
        vm.deal(actor, uint256(a));
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: uint256(a)}("");
        assertTrue(ok1);
        vm.prank(actor);
        c.withdraw();

        // second deposit of b
        vm.deal(actor, uint256(b));
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: uint256(b)}("");
        assertTrue(ok2);

        // general rule: after withdraw clears the entry, the second deposit alone
        // determines the balance; the buggy withdraw leaves the old balance in place.
        assertEq(c.balances(actor), uint256(b));
    }
}

