pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint128).max);
        vm.deal(address(attacker), 2 * amount);
        // deposit via fallback, then withdraw; receive() re-enters withdraw once
        attacker.attack{value: amount}();
        // Reference: reentrant call reverts, outer withdraw's require fails, whole tx reverts,
        // so c still holds the full deposit. Buggy: attacker drains twice, c holds 0.
        assertTrue(address(c).balance == amount);
    }
}

contract Attacker {
    C c;
    bool reentered;

    constructor(C target) {
        c = target;
    }

    function attack() external payable {
        c.withdraw();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdraw();
        }
    }
}

