pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker(c);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18);
        vm.deal(address(attacker), amount);
        attacker.deposit(amount);
        assert(address(c).balance == amount);

        bool ok;
        try attacker.attack() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a re-entrant withdraw attempt must never succeed while
        // completely emptying the contract's ether. The reference reverts the
        // whole withdraw (ok == false); the mutant drains it (ok == true, balance 0).
        assertTrue(!(ok && address(c).balance == 0));
    }
}

contract Attacker {
    C c;
    bool attacked;

    constructor(C _c) {
        c = _c;
    }

    function deposit(uint256 amount) external payable {
        (bool s, ) = address(c).call{value: amount}("");
        require(s);
    }

    function attack() external {
        c.withdraw();
    }

    receive() external payable {
        if (!attacked) {
            attacked = true;
            c.withdraw();
        }
    }
}

