pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address attacker;
    address victim;
    Attacker atk;

    function setUp() public { c = new C(); atk = new Attacker(); attacker = address(atk); victim = address(0xV1); }

    function testFuzz_property(uint256 amtA, uint256 amtV) public {
        vm.assume(amtA > 0 && amtV > 0 && amtA < type(uint256).max - amtV);
        vm.deal(attacker, amtA);
        vm.prank(attacker);
        c.deposit{value: amtA}();
        vm.deal(victim, amtV);
        vm.prank(victim);
        c.deposit{value: amtV}();

        atk.setTarget(address(c));
        bool ok;
        vm.prank(attacker);
        try atk.attack() { ok = true; } catch { ok = false; }

        // In the guarded contract the reentrant withdraw reverts, propagating a revert
        // through the attacker's receive into the outer low-level call, so the outer
        // withdraw reverts and the VICTIM's balance record is preserved.
        // In the mutant the reentrant withdraw succeeds, the outer withdraw completes,
        // and the victim's balance is zeroed.
        assertTrue(ok ? c.balances(victim) == 0 : c.balances(victim) == amtV);
    }
}

contract Attacker {
    C target;
    function setTarget(address t) external { target = C(t); }
    function attack() external {
        target.withdraw();
    }
    receive() external payable {
        // reenter; swallow the revert the guard produces so outer call sees failure only via require
        try target.withdraw() {} catch {}
        // but that swallows... need the reentrant revert to bubble to the outer call's send
        // fallback: to bubble, re-throw when the guard reverts
    }
}

