// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker atk;
    address victim = address(0x1234);

    function setUp() public { c = new C(); atk = new Attacker(); atk.setTarget(address(c)); }

    function testFuzz_property(uint256 vAmt, uint256 aAmt) public {
        // wide admissible domain: positive deposits for victim and attacker
        vAmt = bound(vAmt, 1, 1e18);
        aAmt = bound(aAmt, 1, 1e18);

        // victim deposits vAmt through the fallback
        vm.deal(victim, vAmt);
        vm.prank(victim);
        (bool d1, ) = address(c).call{value: vAmt}("");
        require(d1, "victim deposit failed");

        // adversarial re-entrant attacker deposits aAmt
        vm.deal(address(atk), aAmt);
        vm.prank(address(atk));
        (bool d2, ) = address(c).call{value: aAmt}("");
        require(d2, "attacker deposit failed");

        // attacker triggers withdraw; its receive() re-enters withdraw (caught)
        vm.prank(address(atk));
        try c.withdraw() { /* completed */ } catch { /* reverted */ }

        // Conservation: contract ether must equal recorded unwithdrawn balances.
        // Reference: guard makes the reentrant call revert, balances stay exact.
        // Mutant: reentrant withdraw succeeds and double-drains aAmt, so
        // address(c).balance == vAmt - aAmt < vAmt == c.balances(victim).
        assertTrue(address(c).balance == c.balances(victim));
    }
}

contract Attacker {
    C target;

    function setTarget(address t) external { target = C(t); }

    receive() external payable {
        // re-enter withdraw; in the guarded reference this reverts and is caught,
        // in the mutant it succeeds and drains again
        try target.withdraw() {} catch {}
    }
}
